<?php require_once __DIR__.'/lib/auth.php';require_once __DIR__.'/lib/branding.php';startAppSession();$brand=organizationBrand();$brandName=(string)$brand['name'];$error='';$notice='';$resetLink='';if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){$email=strtolower(trim($_POST['email']??''));$s=db()->prepare('SELECT id,email FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u){$token=bin2hex(random_bytes(32));db()->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$u['id']]);db()->prepare('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([$u['id'],hash('sha256',$token)]);$resetLink='http://127.0.0.1:8001/reset_password.php?token='.$token;@mail($u['email'],$brandName.' password reset',"Open this link within 30 minutes:\n\n$resetLink",'From: no-reply@'.(trim((string)($brand['domain']??''))?:'localhost'));}$notice='If that account exists, a reset link has been created. In this local environment it is shown below.';}$mode='forgot';require __DIR__.'/views/auth.php';
